#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    int left;
    int right;
    int size;
    int index;
    unsigned int priority;
    long long key;
} TreapNode;

typedef struct {
    int size;
    int root_u;
    int root_v;
} Component;

static int n;
static long long k;
static long long *height;
static long long *value_u;
static long long *value_v;
static int *time_of;
static long long *expire_count;

static TreapNode *treap_u;
static TreapNode *treap_v;

static unsigned int rng_state = 2463534242u;

static unsigned int next_random(void) {
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

static int node_size(TreapNode *tree, int root) {
    return root == 0 ? 0 : tree[root].size;
}

static void pull(TreapNode *tree, int root) {
    if (root != 0) {
        tree[root].size = 1
            + node_size(tree, tree[root].left)
            + node_size(tree, tree[root].right);
    }
}

static int compare_pair(long long key1, int index1,
                        long long key2, int index2) {
    if (key1 < key2) return -1;
    if (key1 > key2) return 1;
    if (index1 < index2) return -1;
    if (index1 > index2) return 1;
    return 0;
}

static void split(TreapNode *tree, int root,
                  long long key, int index,
                  int *left_part, int *right_part) {
    if (root == 0) {
        *left_part = 0;
        *right_part = 0;
        return;
    }

    if (compare_pair(tree[root].key, tree[root].index, key, index) < 0) {
        *left_part = root;
        split(tree, tree[root].right, key, index,
              &tree[root].right, right_part);
        pull(tree, root);
    } else {
        *right_part = root;
        split(tree, tree[root].left, key, index,
              left_part, &tree[root].left);
        pull(tree, root);
    }
}

static int insert_node(TreapNode *tree, int root, int node) {
    if (root == 0) {
        tree[node].left = 0;
        tree[node].right = 0;
        tree[node].size = 1;
        return node;
    }

    if (tree[node].priority > tree[root].priority) {
        split(tree, root, tree[node].key, tree[node].index,
              &tree[node].left, &tree[node].right);
        pull(tree, node);
        return node;
    }

    if (compare_pair(tree[node].key, tree[node].index,
                     tree[root].key, tree[root].index) < 0) {
        tree[root].left = insert_node(tree, tree[root].left, node);
    } else {
        tree[root].right = insert_node(tree, tree[root].right, node);
    }

    pull(tree, root);
    return root;
}

static int rank_less(TreapNode *tree, int root,
                     long long key, int index) {
    if (root == 0) return 0;

    if (compare_pair(tree[root].key, tree[root].index, key, index) < 0) {
        return node_size(tree, tree[root].left) + 1
            + rank_less(tree, tree[root].right, key, index);
    }

    return rank_less(tree, tree[root].left, key, index);
}

static int rank_less_equal(TreapNode *tree, int root,
                           long long key, int index) {
    if (root == 0) return 0;

    if (compare_pair(tree[root].key, tree[root].index, key, index) <= 0) {
        return node_size(tree, tree[root].left) + 1
            + rank_less_equal(tree, tree[root].right, key, index);
    }

    return rank_less_equal(tree, tree[root].left, key, index);
}

static long long count_range(TreapNode *tree, int root,
                             long long key, long long lo, long long hi) {
    if (root == 0 || lo > hi || hi < 1 || lo > n) return 0;

    if (lo < 1) lo = 1;
    if (hi > n) hi = n;
    if (lo > hi) return 0;

    return (long long)rank_less_equal(tree, root, key, (int)hi)
         - (long long)rank_less(tree, root, key, (int)lo);
}

static long long query_cross_for_index(int index, const Component *large) {
    long long result = 0;
    long long i = index;

    /* i é o extremo esquerdo: distância até K. */
    result += count_range(treap_u, large->root_u,
                          value_u[index] + k, i + 1, i + k);

    /* i é o extremo direito: distância até K. */
    result += count_range(treap_u, large->root_u,
                          value_u[index] - k, i - k, i - 1);

    /* Na segunda transformação, excluímos a distância exatamente K. */
    result += count_range(treap_v, large->root_v,
                          value_v[index] + k, i + 1, i + k - 1);

    result += count_range(treap_v, large->root_v,
                          value_v[index] - k, i - k + 1, i - 1);

    return result;
}

static void query_small_tree(int root, TreapNode *small_tree,
                             const Component *large, long long *result) {
    if (root == 0) return;

    int left = small_tree[root].left;
    int right = small_tree[root].right;
    int index = small_tree[root].index;

    *result += query_cross_for_index(index, large);

    query_small_tree(left, small_tree, large, result);
    query_small_tree(right, small_tree, large, result);
}

static void move_tree(int root, TreapNode *small_tree,
                      TreapNode *large_tree, int *large_root) {
    if (root == 0) return;

    int left = small_tree[root].left;
    int right = small_tree[root].right;

    small_tree[root].left = 0;
    small_tree[root].right = 0;
    small_tree[root].size = 1;

    *large_root = insert_node(large_tree, *large_root, root);

    move_tree(left, small_tree, large_tree, large_root);
    move_tree(right, small_tree, large_tree, large_root);
