        a = b;
        b = temp;
    }

    long long added_pairs = 0;
    query_small_tree(b.root_u, treap_u, &a, &added_pairs);
    expire_count[0] += 0; /* Mantém a atualização de pares no chamador. */

    /* Os pares são acumulados separadamente no vetor de resultado. */
    extern long long *current_pair_counter;
    *current_pair_counter += added_pairs;

    move_tree(b.root_u, treap_u, treap_u, &a.root_u);
    move_tree(b.root_v, treap_v, treap_v, &a.root_v);

    a.size += b.size;
    return a;
}

long long *current_pair_counter;

static int earlier_priority(int a, int b) {
    if (time_of[a] != time_of[b]) return time_of[a] < time_of[b];
    return a < b;
}

