    value_v = (long long *)calloc((size_t)n + 1, sizeof(long long));
    time_of = (int *)malloc(((size_t)n + 1) * sizeof(int));
    expire_count = (long long *)calloc((size_t)q + 2, sizeof(long long));

    int *left_child = (int *)calloc((size_t)n + 1, sizeof(int));
    int *right_child = (int *)calloc((size_t)n + 1, sizeof(int));
    int *stack = (int *)malloc(((size_t)n + 1) * sizeof(int));
    int *order = (int *)malloc(((size_t)n + 1) * sizeof(int));
    Component *component = (Component *)calloc((size_t)n + 1, sizeof(Component));

    treap_u = (TreapNode *)calloc((size_t)n + 1, sizeof(TreapNode));
    treap_v = (TreapNode *)calloc((size_t)n + 1, sizeof(TreapNode));

