        treap_u[i].index = i;
        treap_u[i].priority = next_random();
        treap_u[i].size = 1;

        treap_v[i].key = value_v[i];
        treap_v[i].index = i;
        treap_v[i].priority = next_random();
        treap_v[i].size = 1;
