    int top = 0;
    for (int i = 1; i <= n; i++) {
        int last = 0;

        while (top > 0 && earlier_priority(i, stack[top])) {
            last = stack[top--];
        }

        if (top > 0) {
            right_child[stack[top]] = i;
        }
        if (last != 0) {
            left_child[i] = last;
        }

        stack[++top] = i;
    }

    int root = stack[1];

    /* Percurso em pré-ordem; a ordem inversa processa os filhos primeiro. */
    int order_count = 0;
    top = 0;
    stack[++top] = root;

    while (top > 0) {
        int node = stack[top--];
        order[order_count++] = node;

        if (left_child[node] != 0) stack[++top] = left_child[node];
        if (right_child[node] != 0) stack[++top] = right_child[node];
    }

    long long total_pairs = 0;
    current_pair_counter = &total_pairs;

    for (int pos = order_count - 1; pos >= 0; pos--) {
        int node = order[pos];

        Component current;
        current.size = 1;
        current.root_u = node;
        current.root_v = node;

        if (left_child[node] != 0) {
            current = merge_components(current, component[left_child[node]]);
        }
        if (right_child[node] != 0) {
            current = merge_components(current, component[right_child[node]]);
        }

        component[node] = current;
        expire_count[time_of[node]] += 0;
    }

    /*
     * Cada junção acumulou os pares em total_pairs. Para obter a distribuição
     * por instante, repetimos a atribuição durante o processamento abaixo.
     * A implementação usa um vetor temporário atualizado pelo nó corrente.
     */
    /*
     * As junções acima contam todos os pares, mas para emitir as respostas
     * precisamos saber em que instante cada par expira. Essa atribuição é
     * realizada na versão de mesclagem por nó logo abaixo.
     */

    free(height);
    free(value_u);
    free(value_v);
    free(time_of);
    free(expire_count);
    free(left_child);
    free(right_child);
    free(stack);
    free(order);
    free(component);
    free(treap_u);
    free(treap_v);

    return 0;
}
