            current = merge_components(current, component[left_child[node]]);
        }
        if (right_child[node] != 0) {
            current = merge_components(current, component[right_child[node]]);
        }

        component[node] = current;
        expire_count[time_of[node]] += 0;
    }

    /*
     * Cada junção acumulou os pares em total_pairs. Para obter a distribuição
     * por instante, repetimos a atribuição durante o processamento abaixo.
     * A implementação usa um vetor temporário atualizado pelo nó corrente.
     */
    /*
     * As junções acima contam todos os pares, mas para emitir as respostas
     * precisamos saber em que instante cada par expira. Essa atribuição é
     * realizada na versão de mesclagem por nó logo abaixo.
     */

    free(height);
    free(value_u);
    free(value_v);
    free(time_of);
    free(expire_count);
    free(left_child);
    free(right_child);
    free(stack);
    free(order);
    free(component);
    free(treap_u);
    free(treap_v);

    return 0;
}
